B.bOW=new A.e("\u0414\u0435\u0440\u0435\u0432\u043e \u041f\u0440\u0438\u043d\u044f\u0442\u0438\u044f","The Tree of Acceptance")
B.bOR=new A.e("\u041f\u0440\u0438\u043d\u044f\u0442\u0438\u0435","Acceptance")
