B.bMv=new A.e(u.jW,"Accepting reality frees up energy for change.")
B.bs2=new A.e("\u0414\u0435\u0440\u0435\u0432\u043e \u041e\u0431\u0438\u0434\u044b","The Tree of Resentment")
