B.bFL=new A.e(u.yI,"Love and kindness are the strongest foundation for life.")
B.bLG=new A.e("\u0414\u0435\u0440\u0435\u0432\u043e \u041e\u0442\u0447\u0443\u0436\u0434\u0435\u043d\u0438\u044f","The Tree of Alienation")
B.bE2=new A.e("\u041e\u0442\u0447\u0443\u0436\u0434\u0435\u043d\u0438\u0435","Alienation")
