B.bBB=new A.e("\u041c\u043d\u0435 \u043d\u0438\u043a\u0442\u043e \u043d\u0435 \u043d\u0443\u0436\u0435\u043d","I don't need anyone")
B.bze=new A.e("\u041c\u043d\u0435 \u043d\u0435\u0442 \u0434\u0435\u043b\u0430 \u0434\u043e \u0447\u0443\u0436\u0438\u0445 \u043f\u0440\u043e\u0431\u043b\u0435\u043c","I don't care about other people's problems")
B.bFC=new A.e("\u041c\u043e\u0451 \u043c\u043d\u0435\u043d\u0438\u0435 \u0438\u043c\u0435\u0435\u0442 \u043f\u0440\u0430\u0432\u043e \u0437\u0432\u0443\u0447\u0430\u0442\u044c","My opinion has a right to be heard")
B.bKH=new A.e("\u042f \u043c\u043e\u0433\u0443 \u0441\u043a\u0430\u0437\u0430\u0442\u044c, \u0447\u0435\u0433\u043e \u0445\u043e\u0447\u0443","I can say what I want")
B.bDy=new A.e("\u041c\u043e\u0438 \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0438\u0435 \u0447\u0443\u0432\u0441\u0442\u0432\u0430 \u043c\u043e\u0436\u043d\u043e \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0442\u044c","My true feelings can be shown")
B.bPp=new A.e("\u041c\u0435\u043d\u044f \u0432\u044b\u0441\u043c\u0435\u044e\u0442","They will laugh at me")
B.bBm=new A.e("\u041f\u0440\u043e\u0449\u0435 \u0441\u043e\u0433\u043b\u0430\u0441\u0438\u0442\u044c\u0441\u044f","It's just easier to agree")
B.bCF=new A.e("\u041c\u043e\u0438 \u0447\u0443\u0432\u0441\u0442\u0432\u0430 \u0432\u0441\u0435\u0445 \u0443\u0442\u043e\u043c\u044f\u0442","My feelings will tire everyone out")
B.bsD=new A.e("\u042f \u0437\u043d\u0430\u044e, \u0447\u0442\u043e \u0434\u043b\u044f \u043c\u0435\u043d\u044f \u0432\u0430\u0436\u043d\u043e","I know what is important to me")
B.bA2=new A.e("\u0417\u0430\u0432\u0442\u0440\u0430 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u0441\u0432\u0435\u0442\u043b\u0435\u0435","Tomorrow might be brighter")
B.bAt=new A.e("\u041c\u0430\u043b\u0435\u043d\u044c\u043a\u0438\u0435 \u0434\u0435\u043b\u0430 \u0442\u043e\u0436\u0435 \u0438\u043c\u0435\u044e\u0442 \u0432\u0435\u0441","Small things matter too")
B.bHz=new A.e("\u0414\u0430\u0436\u0435 \u0442\u044f\u0436\u0451\u043b\u044b\u0439 \u0434\u0435\u043d\u044c \u0447\u0435\u043c\u0443-\u0442\u043e \u0443\u0447\u0438\u0442","Even a hard day teaches something")
B.byP=new A.e("\u042f \u0447\u0430\u0441\u0442\u044c \u0447\u0435\u0433\u043e-\u0442\u043e \u0431\u043e\u043b\u044c\u0448\u0435\u0433\u043e","I am part of something bigger")
B.bLq=new A.e("\u0412\u043f\u0435\u0440\u0435\u0434\u0438 \u043d\u0438\u0447\u0435\u0433\u043e \u0445\u043e\u0440\u043e\u0448\u0435\u0433\u043e","Nothing good lies ahead")
B.bvt=new A.e("\u041b\u0438\u0448\u044c \u0431\u044b \u0443\u0431\u0438\u0442\u044c \u0432\u0440\u0435\u043c\u044f","Just to kill some time")
B.bB9=new A.e("\u041d\u0435\u043f\u0440\u043e\u0447\u0438\u0442\u0430\u043d\u043d\u043e\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435","An Unread Message")
B.bAy=new A.e(u.m,"You send something important to a close person. Three hours pass. The message is read, but there is no reply.")
B.bL1=new A.e("\u041d\u0430\u0432\u0435\u0440\u043d\u043e\u0435, {\u0437\u0430\u043d\u044f\u0442|\u0437\u0430\u043d\u044f\u0442\u0430}. \u041e\u0442\u0432\u0435\u0442\u0438\u0442, \u043a\u043e\u0433\u0434\u0430 \u0441\u043c\u043e\u0436\u0435\u0442.","They must be busy. They'll reply when they can.")
B.bF7=new A.e("\u041f\u043e\u0445\u043e\u0436\u0435, \u044f {\u043d\u0430\u043f\u0438\u0441\u0430\u043b|\u043d\u0430\u043f\u0438\u0441\u0430\u043b\u0430} \u0447\u0442\u043e-\u0442\u043e \u043d\u0435 \u0442\u043e. \u041e\u043f\u044f\u0442\u044c \u0432\u0441\u0451 \u0438\u0441\u043f\u043e\u0440\u0442\u0438\u043b\u043e\u0441\u044c \u0438\u0437-\u0437\u0430 \u043c\u0435\u043d\u044f.","Looks like I wrote something wrong. Everything is ruined because of me again.")
B.bMq=new A.e("\u0417\u043d\u0430\u0447\u0438\u0442, \u0438\u0433\u043d\u043e\u0440\u0438\u0440\u0443\u0435\u0442 \u0441\u043f\u0435\u0446\u0438\u0430\u043b\u044c\u043d\u043e. \u0417\u0430\u043f\u043e\u043c\u043d\u044e.","So they are ignoring me on purpose. I'll remember that.")
B.btW=new A.e("\u041d\u0443 \u0438 \u043b\u0430\u0434\u043d\u043e. \u041d\u0438\u043a\u043e\u043c\u0443 \u044f, \u0432\u0438\u0434\u043d\u043e, \u043d\u0435 {\u043d\u0443\u0436\u0435\u043d|\u043d\u0443\u0436\u043d\u0430}.","Oh well. It seems no one needs me anyway.")
B.bLY=new A.e("\u041d\u0430\u043f\u0438\u0448\u0443 \u0435\u0449\u0451 \u0440\u0430\u0437 \u2014 \u0432\u0434\u0440\u0443\u0433 \u043d\u0435 {\u0437\u0430\u043c\u0435\u0442\u0438\u043b|\u0437\u0430\u043c\u0435\u0442\u0438\u043b\u0430}.","I'll write again\u2014maybe they just didn't notice.")
B.bOE=new A.e("\u041f\u0435\u0440\u0432\u0430\u044f \u043d\u0435\u0443\u0434\u0430\u0447\u0430","The First Failure")
B.bv8=new A.e(u.mA,"You prepare for a long time for an important event\u2014an exam, a speech, a match\u2014and you fail it right in front of everyone.")
B.bzM=new A.e(u.C8,"It hurts. I'll figure out what went wrong and try again.")
B.bKy=new A.e(u.cF,"That's just it: nothing ever works out for me.")
B.bAW=new A.e(u.mg,"Why does this always happen to me?")
B.bGy=new A.e(u.DC,"Today is for rest. Tomorrow is for one small step.")
B.bMH=new A.e(u.yW,"Now everyone will see what I am truly worth.")
B.bF3=new A.e("\u0418\u0434\u0435\u044e \u043e\u0442\u0432\u0435\u0440\u0433\u043b\u0438","The Idea Is Rejected")
B.bDz=new A.e(u.b8,"You offer an idea you are proud of. They listen to it\u2014and choose a different one.")
B.bQL=new A.e(u.AP,"Not this time. The idea is not me, and I am doing completely fine.")
B.bSN=new A.e("\u041a\u0430\u043a \u0432\u0441\u0435\u0433\u0434\u0430. \u041c\u0438\u0440 \u043d\u0435\u0441\u043f\u0440\u0430\u0432\u0435\u0434\u043b\u0438\u0432 \u043a\u043e \u043c\u043d\u0435.","As always. The world is unfair to me.")
B.bDc=new A.e(u.c,"I won't bother sharing my ideas anymore; they are just silly.")
B.bHb=new A.e(u.Ad,"I'll ask why their choice is better\u2014it might come in handy.")
B.bQf=new A.e(u.I,"I won't suggest anything ever again. What's the point of even trying.")
B.bsi=new A.e("\u041f\u043b\u0430\u043d\u044b \u0440\u0443\u0448\u0430\u0442\u0441\u044f","Plans Fall Apart")
B.bM_=new A.e(u.fW,"You look forward to a trip or a holiday for a long time. On the final day, everything gets cancelled\u2014no one's fault, that's just how it turned out.")
B.bIb=new A.e("\u0416\u0430\u043b\u044c. \u041f\u043e\u0433\u0440\u0443\u0449\u0443 \u043d\u0435\u043c\u043d\u043e\u0433\u043e \u2014 \u0438\u043c\u0435\u044e \u043f\u0440\u0430\u0432\u043e.","What a shame. I'll allow myself to feel sad for a bit\u2014I have a right to do so.")
B.bEj=new A.e(u.o5,"This shouldn't have happened! Everything ought to be different.")
B.bIf=new A.e(u.r,"And that is exactly why planning is pointless. Everything is meaningless.")
B.bHC=new A.e(u.xt,"It already happened. What can be done instead\u2014even if it's just a little thing?")
B.bvO=new A.e(u.EW,"Of course. Nothing ever depends on me.")
B.bMO=new A.e("\u0427\u0443\u0436\u0438\u0435 \u0441\u043b\u0451\u0437\u044b","Someone Else's Tears")
B.buq=new A.e(u.l6,"A person with whom you have a strained relationship gets bad news in front of everyone and can barely hold back tears.")
B.bPl=new A.e(u.sC,"I'll go over and quietly ask if they need help. We are all connected.")
B.buN=new A.e("\u041d\u0435 \u043c\u043e\u0451 \u0434\u0435\u043b\u043e. \u0423 \u0432\u0441\u0435\u0445 \u0441\u0432\u043e\u0438 \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u044b.","Not my business. Everyone has their own problems.")
B.bRl=new A.e(u.ex,"Big deal. I've had it worse, and no one pitied me.")
B.bzI=new A.e("\u041c\u043e\u0436\u0435\u0442, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u043e\u043d \u0438 \u0431\u044b\u043b \u0441\u043e \u043c\u043d\u043e\u0439 {\u0440\u0435\u0437\u043e\u043a|\u0440\u0435\u0437\u043a\u0430}. \u0423 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0441\u0432\u043e\u044f \u043f\u0440\u0438\u0447\u0438\u043d\u0430.","Maybe that's why they were sharp with me. Everyone has their own reason.")
B.bBf=new A.e(u.jL,"I want to help, but everyone is watching. Better to keep a low profile.")
B.brA=new A.e("\u0414\u0440\u0443\u0433\u043e\u0435 \u043c\u043d\u0435\u043d\u0438\u0435","A Different Opinion")
B.bBZ=new A.e(u.qW,"At a meeting (class, gathering, or in a chat), they ask: 'Who has a different opinion?' You do.")
B.bRG=new A.e("\u0421\u043a\u0430\u0436\u0443: \u043c\u043d\u0435 \u0435\u0441\u0442\u044c \u0447\u0442\u043e \u0441\u043a\u0430\u0437\u0430\u0442\u044c.","I'll speak up: I have something to say.")
B.bLn=new A.e("\u041f\u0440\u043e\u043c\u043e\u043b\u0447\u0443. \u0422\u0438\u0448\u0435 \u0435\u0434\u0435\u0448\u044c \u2014 \u0434\u0430\u043b\u044c\u0448\u0435 \u0431\u0443\u0434\u0435\u0448\u044c.","I'll keep quiet. Slow and steady wins the race.")
B.brS=new A.e("\u0412\u0434\u0440\u0443\u0433 \u0437\u0430\u0441\u043c\u0435\u044e\u0442. \u041b\u0443\u0447\u0448\u0435 \u043c\u043e\u043b\u0447\u0430\u0442\u044c.","What if they laugh at me. Better to stay silent.")
B.bC0=new A.e("\u0421\u043a\u0430\u0436\u0443 \u043a\u043e\u0440\u043e\u0442\u043a\u043e, \u0434\u0430\u0436\u0435 \u0435\u0441\u043b\u0438 \u0433\u043e\u043b\u043e\u0441 \u0434\u0440\u043e\u0436\u0438\u0442.","I'll say it briefly, even if my voice shakes.")
B.bL9=new A.e(u.cX,"I'll say it\u2014and then they'll use it against me.")
B.bSI=new A.e("\u041f\u0443\u0441\u0442\u043e\u0435 \u0432\u043e\u0441\u043a\u0440\u0435\u0441\u0435\u043d\u044c\u0435","An Empty Sunday")
B.bMg=new A.e(u.z6,"Sunday evening after a long week. There is nothing left to do\u2014and it feels empty inside.")
B.bvA=new A.e("\u041d\u0430\u0439\u0434\u0443 \u0432 \u044d\u0442\u043e\u043c \u0434\u043d\u0435 \u043e\u0434\u043d\u0443 \u043c\u0430\u043b\u0435\u043d\u044c\u043a\u0443\u044e \u0438\u0441\u043a\u0440\u0443.","I'll find one tiny spark in this day.")
B.by4=new A.e(u.EV,"Just to kill some time\u2014I'll turn something on until late at night.")
B.bIZ=new A.e("\u0410 \u043a\u0430\u043a\u0430\u044f \u0440\u0430\u0437\u043d\u0438\u0446\u0430? \u0412\u0441\u0451 \u0440\u0430\u0432\u043d\u043e \u0432\u0441\u0451 \u0441\u043e\u0442\u0440\u0451\u0442\u0441\u044f.","What difference does it make? It'll all be erased anyway.")
B.bKq=new A.e(u.B1,"I'll do one small thing that is truly important to me.")
B.bDd=new A.e(u.Et,"I'll just rest guilt-free. You don't have to earn this.")
B.bCB=new A.e("\u041f\u043e\u0445\u0432\u0430\u043b\u0430","Praise")
B.bSA=new A.e("\u0422\u0435\u0431\u044f \u0438\u0441\u043a\u0440\u0435\u043d\u043d\u0435 \u0445\u0432\u0430\u043b\u044f\u0442 \u0437\u0430 \u0441\u0434\u0435\u043b\u0430\u043d\u043d\u043e\u0435.","You are sincerely praised for what you have done.")
B.bIj=new A.e("\u0421\u043f\u0430\u0441\u0438\u0431\u043e. \u041c\u043d\u0435 \u043f\u0440\u0438\u044f\u0442\u043d\u043e.","Thank you. It feels nice.")
B.bG_=new A.e("\u042d\u0442\u043e \u043e\u043d\u0438 \u0438\u0437 \u0432\u0435\u0436\u043b\u0438\u0432\u043e\u0441\u0442\u0438.","They are just saying that to be polite.")
B.bwS=new A.e(u.BT,"Now I have to keep the bar high, otherwise I'll disappoint them.")
B.bN9=new A.e("\u0418\u043d\u0442\u0435\u0440\u0435\u0441\u043d\u043e, \u0447\u0442\u043e \u0438\u043c \u043e\u0442 \u043c\u0435\u043d\u044f \u043d\u0443\u0436\u043d\u043e?","I wonder what they want from me.")
B.btR=new A.e(u.nP,"I'll celebrate: a small victory counts too.")
B.bOh=new A.e("\u041d\u0443\u0436\u043d\u0430 \u0442\u0438\u0448\u0438\u043d\u0430","Needing Quiet")
B.bPs=new A.e(u.pr,"Tomorrow is an important day, but people are making noise late into the night at home (in the dorm, or the neighbors).")
B.bPE=new A.e("\u041f\u043e\u043f\u0440\u043e\u0448\u0443 \u0432\u0435\u0436\u043b\u0438\u0432\u043e: \u043c\u043e\u0451 \u0437\u0430\u0432\u0442\u0440\u0430 \u0442\u043e\u0436\u0435 \u0432\u0430\u0436\u043d\u043e.","I'll ask politely: my tomorrow matters too.")
B.bxQ=new A.e("\u041d\u0435 \u0431\u0443\u0434\u0443 \u043d\u0438\u043a\u043e\u0433\u043e \u043d\u0430\u043f\u0440\u044f\u0433\u0430\u0442\u044c. \u042f \u0438 \u0442\u0430\u043a \u043e\u0431\u0443\u0437\u0430.","I won't burden anyone. I'm a nuisance anyway.")
B.buz=new A.e("\u041f\u043e\u0442\u0435\u0440\u043f\u043b\u044e. \u041c\u043e\u0438 \u043d\u0443\u0436\u0434\u044b \u2014 \u043f\u043e\u0442\u043e\u043c.","I'll put up with it. My needs come later.")
B.bSK=new A.e("\u0411\u0435\u0441\u043f\u043e\u043b\u0435\u0437\u043d\u043e: \u0432\u0441\u0451 \u0440\u0430\u0432\u043d\u043e \u043d\u0435 \u043f\u043e\u0441\u043b\u0443\u0448\u0430\u044e\u0442.","It's useless: they won't listen anyway.")
B.buX=new A.e("\u041f\u0440\u044f\u043c\u043e \u0441\u043a\u0430\u0436\u0443, \u0447\u0442\u043e \u043c\u043d\u0435 \u043d\u0443\u0436\u043d\u043e.","I'll say directly what I need.")
B.bGo=new A.e("\u0412\u044b\u0445\u043e\u0434\u043d\u043e\u0439 \u0431\u0435\u0437 \u0441\u0438\u043b","A Exhausted Day Off")
B.bwH=new A.e(u.uo,"It's your day off, but your to-do list is long, and you have almost no strength left.")
B.brd=new A.e(u.lJ,"I'll rest first. Rest doesn't need to be earned.")
B.bDb=new A.e(u.k4,"Rest has to be earned. I'll finish everything first.")
B.bL2=new A.e("\u0421\u0434\u0435\u043b\u0430\u044e \u043e\u0434\u0438\u043d \u043f\u0443\u043d\u043a\u0442, \u0430 \u043f\u043e\u0442\u043e\u043c \u043e\u0442\u0434\u044b\u0445.","I'll do one item, then rest.")
B.bxG=new A.e("\u0412\u0441\u0451 \u0440\u0430\u0432\u043d\u043e \u043d\u0435 \u0443\u0441\u043f\u0435\u044e. \u041d\u0435\u0442 \u0441\u043c\u044b\u0441\u043b\u0430 \u043d\u0430\u0447\u0438\u043d\u0430\u0442\u044c.","I won't make it anyway. There is no point in starting.")
B.bSO=new A.e(u.Eb,"I'll scroll through my feed until evening, just to avoid thinking.")
B.bwD=new A.e("\u0417\u0430\u0431\u044b\u0442\u043e\u0435 \u043e\u0431\u0435\u0449\u0430\u043d\u0438\u0435","A Forgotten Promise")
B.bOC=new A.e(u.gR,"You forget about a promise, and your friend gets into trouble because of it.")
B.bLy=new A.e(u.z3,"There is a mistake, but I am not a mistake. I will apologize and make it right.")
B.bwl=new A.e("\u042f \u0443\u0436\u0430\u0441\u043d\u044b\u0439 \u0447\u0435\u043b\u043e\u0432\u0435\u043a. \u0412\u0435\u0447\u043d\u043e \u0432\u0441\u0451 \u043f\u043e\u0440\u0447\u0443.","I am a terrible person. I always ruin everything.")
B.bRV=new A.e("\u041f\u0443\u0441\u0442\u044c \u0441\u0430\u043c \u043d\u0430\u043f\u043e\u043c\u0438\u043d\u0430\u0435\u0442. \u041c\u043d\u0435 \u0432\u0441\u0435 \u0434\u043e\u043b\u0436\u043d\u044b.","They should have reminded me themselves. Everyone owes me.")
B.bNk=new A.e(u.D7,"Now they will definitely stop talking to me.")
B.bAM=new A.e(u.kF,"I will keep making up for it until I earn forgiveness.")
B.bwJ=new A.e("\u041d\u0435\u0443\u0434\u0430\u0447\u043d\u043e\u0435 \u0444\u043e\u0442\u043e","An Unflattering Photo")
B.btY=new A.e(u.t9,"You see a candid photo of yourself where you don't look at all the way you'd want to.")
B.bCV=new A.e(u.rN,"Just a normal photo of a real person. I am here, and that is good.")
B.bAL=new A.e("\u0423\u0436\u0430\u0441. \u0421\u043e \u043c\u043d\u043e\u0439 \u0447\u0442\u043e-\u0442\u043e \u043d\u0435 \u0442\u0430\u043a.","Terrible. There is something wrong with me.")
B.bLV=new A.e("\u0411\u043e\u043b\u044c\u0448\u0435 \u043d\u0438\u043a\u0430\u043a\u0438\u0445 \u0444\u043e\u0442\u043e. \u041d\u0435 \u0432\u044b\u0441\u043e\u0432\u044b\u0432\u0430\u0442\u044c\u0441\u044f.","No more photos. Keep a low profile.")
B.bt5=new A.e("\u041f\u043e\u0441\u043c\u0435\u044e\u0441\u044c. \u042f {\u0442\u0430\u043a\u043e\u0439|\u0442\u0430\u043a\u0430\u044f}, {\u043a\u0430\u043a\u043e\u0439|\u043a\u0430\u043a\u0430\u044f} \u0435\u0441\u0442\u044c.","I'll have a laugh. I am who I am.")
B.bw3=new A.e("\u0412\u0441\u0435 \u043d\u0430\u0432\u0435\u0440\u043d\u044f\u043a\u0430 \u0431\u0443\u0434\u0443\u0442 \u0441\u043c\u0435\u044f\u0442\u044c\u0441\u044f.","Everyone will probably laugh at me.")
B.bPh=new A.e("\u041d\u043e\u0432\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f","A New Group")
B.bON=new A.e(u.Ff,"You join a new group for the first time: a class, a team, a club, or a workspace.")
B.bBC=new A.e("\u041b\u044e\u0434\u0438 \u043c\u043e\u0433\u0443\u0442 \u043f\u043e\u043c\u043e\u0447\u044c. \u0421\u043f\u0440\u043e\u0448\u0443, \u0447\u0442\u043e \u0442\u0443\u0442 \u043a\u0430\u043a.","People can be helpful. I'll ask how things work here.")
B.bM3=new A.e(u.W,"I'll keep my distance and watch out for anyone dangerous.")
B.bvf=new A.e("\u0423 \u043d\u0438\u0445 \u0432\u0441\u0451 \u0434\u0430\u0432\u043d\u043e \u0441\u0432\u043e\u0451. \u041d\u0438\u043a\u043e\u043c\u0443 \u044f \u0442\u0443\u0442 \u043d\u0435 {\u043d\u0443\u0436\u0435\u043d|\u043d\u0443\u0436\u043d\u0430}.","They already have their own tight group. No one needs me here.")
B.bHY=new A.e(u.vB,"I wonder who is here\u2014maybe I'll find my kind of people.")
B.bLf=new A.e(u.ny,"I'll stay silent all evening so I don't say something silly.")
B.buZ=new A.e("\u041d\u0435 \u0432\u0435\u0440\u043d\u0443\u043b\u0438","Not Returned")
B.bzV=new A.e(u.Z,"A friend promised to return your thing yesterday, but they haven't and are staying silent.")
B.bGY=new A.e("\u041d\u0430\u0432\u0435\u0440\u043d\u043e\u0435, {\u0437\u0430\u0431\u044b\u043b|\u0437\u0430\u0431\u044b\u043b\u0430}. \u041d\u0430\u043f\u043e\u043c\u043d\u044e \u2014 \u044d\u0442\u043e \u043d\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u043e.","They probably forgot. I'll remind them\u2014that's completely normal.")
B.bG4=new A.e("\u0422\u0430\u043a \u0438 \u0435\u0441\u0442\u044c: \u0432\u0435\u0440\u0438\u0442\u044c \u043d\u0435\u043b\u044c\u0437\u044f \u043d\u0438\u043a\u043e\u043c\u0443.","Just as I thought: you can't trust anyone.")
B.bz0=new A.e("\u0411\u043e\u043b\u044c\u0448\u0435 \u043d\u0438\u043a\u043e\u043c\u0443 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0430\u043c.","I'm never lending anything to anyone again.")
B.bOu=new A.e("{\u0421\u0430\u043c|\u0421\u0430\u043c\u0430} {\u0432\u0438\u043d\u043e\u0432\u0430\u0442|\u0432\u0438\u043d\u043e\u0432\u0430\u0442\u0430}, \u0447\u0442\u043e {\u0434\u0430\u043b|\u0434\u0430\u043b\u0430}. \u0412\u0435\u0447\u043d\u043e \u0432\u0441\u0451 \u043f\u043e\u0440\u0447\u0443.","It's my own fault for lending it. I always ruin everything.")
B.bGe=new A.e("\u0417\u043d\u0430\u0447\u0438\u0442, \u0441\u043f\u0435\u0446\u0438\u0430\u043b\u044c\u043d\u043e. \u041d\u0435 \u043f\u0440\u043e\u0449\u0443.","That means they did it on purpose. I won't forgive this.")
B.bKF=new A.e("\u041d\u0435\u0437\u043d\u0430\u043a\u043e\u043c\u0435\u0446 \u0441\u043f\u0440\u0430\u0448\u0438\u0432\u0430\u0435\u0442 \u0434\u043e\u0440\u043e\u0433\u0443","A Stranger Asks for Directions")
B.bCq=new A.e(u.cy,"A stranger on the street asks you for directions.")
B.bHE=new A.e(u.Bv,"I'll tell them: most people wish me no harm.")
B.bKV=new A.e("\u041d\u0430\u0432\u0435\u0440\u043d\u044f\u043a\u0430 \u0443\u043b\u043e\u0432\u043a\u0430. \u041f\u0440\u043e\u0439\u0434\u0443 \u043c\u0438\u043c\u043e.","It's probably a trick. I'll just walk past.")
B.bBn=new A.e(u.yu,"I'll help with a smile: it feels nice to bring a little joy.")
B.bSE=new A.e("\u0420\u0430\u0441\u0442\u0435\u0440\u044f\u044e\u0441\u044c \u0438 \u043f\u0440\u043e\u043c\u043e\u043b\u0447\u0443.","I'll get flustered and stay silent.")
B.bGd=new A.e(u.CT,"Let others help, I have enough of my own business to attend to.")
B.bAN=new A.e("\u0422\u0440\u0435\u0442\u0438\u0439 \u0434\u0435\u043d\u044c \u043d\u0435 \u0432\u044b\u0445\u043e\u0434\u0438\u0442","Stuck for Three Days")
B.bKm=new A.e(u.a,"A task (school, work, or chores) hasn't been working out for three days now.")
B.bxZ=new A.e("\u041f\u043e\u043f\u0440\u043e\u0448\u0443 \u043f\u043e\u043c\u043e\u0449\u0438: \u044f \u043c\u043e\u0433\u0443 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u044c.","I'll ask for help: I am allowed to ask.")
B.bRX=new A.e("\u0415\u0441\u043b\u0438 \u043f\u043e\u043f\u0440\u043e\u0448\u0443, \u043f\u043e\u0439\u043c\u0443\u0442, \u0447\u0442\u043e \u044f \u043d\u0435\u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e {\u0445\u043e\u0440\u043e\u0448|\u0445\u043e\u0440\u043e\u0448\u0430}.","If I ask, they'll realize I'm not good enough.")
B.bSz=new A.e("\u041f\u0443\u0441\u0442\u044c \u043a\u0442\u043e-\u043d\u0438\u0431\u0443\u0434\u044c \u0440\u0435\u0448\u0438\u0442 \u0437\u0430 \u043c\u0435\u043d\u044f.","Let someone else solve it for me.")
B.bOm=new A.e("\u041f\u043e\u043f\u0440\u043e\u0431\u0443\u044e \u0441\u043e\u0432\u0441\u0435\u043c \u0434\u0440\u0443\u0433\u0438\u043c \u0441\u043f\u043e\u0441\u043e\u0431\u043e\u043c.","I'll try it in a completely different way.")
B.bIz=new A.e("\u041d\u0438\u043a\u0442\u043e \u043d\u0435 \u0434\u043e\u043b\u0436\u0435\u043d \u0432\u0438\u0434\u0435\u0442\u044c, \u0447\u0442\u043e \u043c\u043d\u0435 \u0442\u0440\u0443\u0434\u043d\u043e.","No one should see that I am struggling.")
B.bCU=new A.e("\u041e\u043f\u0430\u0437\u0434\u044b\u0432\u0430\u0435\u0442 \u0438 \u043d\u0435 \u043e\u0442\u0432\u0435\u0447\u0430\u0435\u0442","Late and Not Answering")
B.bOq=new A.e(u.A,"A close person is forty minutes late for your meeting and isn't picking up the phone.")
B.bRO=new A.e(u.gj,"They must have been held up by something. They haven't forgotten about me.")
B.bOr=new A.e("\u0421\u043e \u043c\u043d\u043e\u0439 \u0442\u0430\u043a \u0432\u0441\u0435\u0433\u0434\u0430. \u041d\u0438\u043a\u043e\u043c\u0443 \u044f \u043d\u0435 {\u043d\u0443\u0436\u0435\u043d|\u043d\u0443\u0436\u043d\u0430}.","It's always like this with me. No one needs me anyway.")
B.bwI=new A.e(u.lA,"They are ignoring me on purpose. I'll have to check where they were.")
B.bAY=new A.e(u.DY,"What if something happened?! Something terrible is about to happen.")
B.bs_=new A.e(u.r2,"I'll wait, and then calmly mention that waiting was unpleasant for me.")
B.bJ5=new A.e("\u041d\u043e\u0432\u043e\u0435 \u0443\u043c\u0435\u043d\u0438\u0435","A New Skill")
B.bRB=new A.e(u.DX,"You start learning something new (a language, an instrument, a sport), and it goes poorly during the first few weeks.")
B.bRP=new A.e("\u041e\u0448\u0438\u0431\u0430\u0442\u044c\u0441\u044f \u2014 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e, \u044f \u0443\u0447\u0443\u0441\u044c.","Making mistakes is safe, I am learning.")
B.bO0=new A.e("\u041d\u0435 \u043c\u043e\u0451. \u042f \u043d\u0435 \u0441\u043f\u0440\u0430\u0432\u043b\u044e\u0441\u044c.","Not my thing. I won't handle it.")
B.bJE=new A.e("\u0412\u0441\u0435 \u0431\u044b\u0441\u0442\u0440\u0435\u0435 \u043c\u0435\u043d\u044f. \u042f \u043d\u0435\u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e {\u0445\u043e\u0440\u043e\u0448|\u0445\u043e\u0440\u043e\u0448\u0430}.","Everyone is faster than me. I am not good enough.")
B.bu0=new A.e(u.d,"I'll practice for just 10 minutes\u2014step by step.")
B.bF6=new A.e(u.x,"I'll quit before anyone sees how bad I am at this.")
B.bQI=new A.e("\u041d\u0435\u0434\u0435\u043b\u044f \u0434\u043e \u0441\u0440\u043e\u043a\u0430","A Week to the Deadline")
B.bOF=new A.e(u.t5,"There is a week left before a big deadline, and nothing has been started yet.")
B.bwn=new A.e(u.Bh,"I'll start with the simplest piece: some things depend on me.")
B.bMo=new A.e("\u0412\u0441\u0451, \u043d\u0435 \u0443\u0441\u043f\u0435\u0442\u044c. \u042f \u043d\u0435 \u0441\u043f\u0440\u0430\u0432\u043b\u044e\u0441\u044c.","That's it, no time left. I won't handle it.")
B.bry=new A.e("\u041e\u0442\u043b\u043e\u0436\u0443 \u0435\u0449\u0451 \u043d\u0430 \u0434\u0435\u043d\u0451\u043a: \u0441\u0438\u043b \u0432\u0441\u0451 \u0440\u0430\u0432\u043d\u043e \u043d\u0435\u0442.","I'll put it off for one more day: I don't have the energy anyway.")
B.bv7=new A.e("\u0421 \u0437\u0430\u0432\u0430\u043b\u0430\u043c\u0438 \u044f \u0443\u0436\u0435 {\u0441\u043f\u0440\u0430\u0432\u043b\u044f\u043b\u0441\u044f|\u0441\u043f\u0440\u0430\u0432\u043b\u044f\u043b\u0430\u0441\u044c} \u2014 \u0441\u043f\u0440\u0430\u0432\u043b\u044e\u0441\u044c \u0438 \u0441\u0435\u0439\u0447\u0430\u0441.","I've handled pile-ups before\u2014I'll handle this one too.")
B.by6=new A.e(u.ux,"If it can't be perfect, it's better not to do it at all.")
B.bBy=new A.e("\u0427\u0442\u043e-\u0442\u043e \u0441\u043b\u043e\u043c\u0430\u043b\u043e\u0441\u044c","Something Is Broken")
B.bxD=new A.e(u.fj,"Something useful breaks at home, and the repairman will take a long time to arrive.")
B.bsv=new A.e(u.Ef,"I have some skills. I'll look up how to fix it and give it a try.")
B.bGl=new A.e(u.eQ,"I don't understand anything about this, it's not for me.")
B.bAK=new A.e("\u041f\u043e\u0447\u0435\u043c\u0443 \u0432\u0441\u0451 \u043b\u043e\u043c\u0430\u0435\u0442\u0441\u044f \u0438\u043c\u0435\u043d\u043d\u043e \u0443 \u043c\u0435\u043d\u044f?","Why does everything break specifically at my place?")
B.bNl=new A.e(u.iQ,"I'll ask a neighbor or a friend\u2014people can be helpful.")
B.bC1=new A.e("\u041d\u0443 \u0438 \u043f\u0443\u0441\u0442\u044c \u0441\u043b\u043e\u043c\u0430\u043d\u043e. \u041a\u0430\u043a\u0430\u044f \u0440\u0430\u0437\u043d\u0438\u0446\u0430.","Let it stay broken then. What difference does it make.")
B.buf=new A.e("\u041a\u0440\u0438\u0442\u0438\u043a\u0430 \u043f\u0440\u0438 \u0432\u0441\u0435\u0445","Public Criticism")
B.bBb=new A.e(u.sy,"An authority figure (a teacher, supervisor, or coach) harshly criticizes your work in front of everyone.")
B.bAv=new A.e(u.Fc,"It's unpleasant. The criticism is about the work, not about me.")
B.bBa=new A.e("\u0412\u0441\u0451 \u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u043e: \u044f \u043d\u0438 \u043d\u0430 \u0447\u0442\u043e \u043d\u0435 \u0433\u043e\u0436\u0443\u0441\u044c.","They are right: I am good for nothing.")
B.bQk=new A.e("\u041f\u0440\u043e\u0441\u0442\u043e \u0438\u0449\u0435\u0442 \u043f\u043e\u0432\u043e\u0434. \u0416\u0434\u0438 \u0443\u0434\u0430\u0440\u0430 \u0432 \u0441\u043f\u0438\u043d\u0443.","They are just looking for an excuse. Expect a stab in the back.")
B.bCa=new A.e(u.c7,"I'll ask exactly what needs fixing. I can try a different way.")
B.bu8=new A.e(u.l,"I won't show anything else until it is absolutely perfect.")
B.bxp=new A.e("\u041a\u043e\u043c\u0430\u043d\u0434\u0430 \u043f\u0440\u043e\u0438\u0433\u0440\u0430\u043b\u0430","The Team Lost")
B.bEK=new A.e(u.dy,"Your team loses, and someone blames you for it.")
B.bBM=new A.e("\u041f\u0440\u043e\u0438\u0433\u0440\u044b\u0448\u0438 \u0431\u044b\u0432\u0430\u043b\u0438 \u0438 \u0440\u0430\u043d\u044c\u0448\u0435 \u2014 \u044f \u0438\u0445 {\u043f\u0435\u0440\u0435\u0436\u0438\u043b|\u043f\u0435\u0440\u0435\u0436\u0438\u043b\u0430}.","Losses have happened before\u2014I survived them.")
B.bCn=new A.e("\u041e\u043f\u044f\u0442\u044c \u0438\u0437-\u0437\u0430 \u043c\u0435\u043d\u044f. \u0412\u0435\u0447\u043d\u043e \u044f \u0432\u0441\u0451 \u043f\u043e\u0440\u0447\u0443.","It's because of me again. I always ruin everything.")
B.bJL=new A.e("\u0412\u0441\u0435 \u043f\u043b\u043e\u0445\u043e \u0438\u0433\u0440\u0430\u043b\u0438, \u0430 {\u0432\u0438\u043d\u043e\u0432\u0430\u0442|\u0432\u0438\u043d\u043e\u0432\u0430\u0442\u0430} \u044f? \u041d\u0435\u0441\u043f\u0440\u0430\u0432\u0435\u0434\u043b\u0438\u0432\u043e!","Everyone played poorly, but I'm to blame? That's unfair!")
B.bOK=new A.e(u.aC,"I'll leave the team. Nothing depends on me anyway.")
B.byq=new A.e(u.CS,"I'll stay silent, even though it's not true. It's just easier to agree.")
B.bIx=new A.e("\u0421\u0442\u0430\u0440\u0430\u044f \u043e\u0431\u0438\u0434\u0430","An Old Hurt")
B.bH2=new A.e(u.yJ,"You suddenly remember a time when someone deeply hurt you.")
B.bP2=new A.e(u.F5,"It happened, and it hurts. The past can't be changed, and I am here now.")
B.bMz=new A.e(u.up,"I'm replaying what I should have said again. If only back then...")
B.byl=new A.e("\u042f \u044d\u0442\u043e\u0433\u043e \u043d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 \u043f\u0440\u043e\u0449\u0443.","I will never forgive this.")
B.bQQ=new A.e("\u041f\u043e\u0437\u0432\u043e\u043b\u044e \u0441\u0435\u0431\u0435 \u043f\u043e\u0433\u0440\u0443\u0441\u0442\u0438\u0442\u044c \u043e\u0431 \u044d\u0442\u043e\u043c.","I'll allow myself to feel sad about it.")
B.byI=new A.e("\u0412\u043e\u0442 \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u043b\u044e\u0434\u044f\u043c \u0432\u0435\u0440\u0438\u0442\u044c \u043d\u0435\u043b\u044c\u0437\u044f.","And that's exactly why you can't trust people.")
B.bCw=new A.e("\u041b\u0438\u0432\u0435\u043d\u044c","Downpour")
B.bHf=new A.e(u.vX,"You are about to go out for a walk, but a heavy rain starts and lasts all day.")
B.brX=new A.e(u.ya,"The weather doesn't ask permission. I'll figure out something to do at home.")
B.bJV=new A.e("\u0412\u0441\u0451 \u0432\u0441\u0435\u0433\u0434\u0430 \u043f\u0440\u043e\u0442\u0438\u0432 \u043c\u0435\u043d\u044f.","Everything is always against me.")
B.brx=new A.e(u.nf,"What's the point of even getting ready. Why even try.")
B.bOi=new A.e(u.Bo,"I'll listen to the rain\u2014there is beauty in it too.")
B.bKI=new A.e("\u042d\u0442\u043e \u043f\u0440\u043e\u0439\u0434\u0451\u0442. \u0417\u0430\u0432\u0442\u0440\u0430 \u0431\u0443\u0434\u0435\u0442 \u0434\u0440\u0443\u0433\u043e\u0439 \u0434\u0435\u043d\u044c.","This will pass. Tomorrow will be a new day.")
B.bt3=new A.e("\u0417\u0430\u0431\u043e\u043b\u0435\u0442\u044c \u043d\u0435 \u0432\u043e\u0432\u0440\u0435\u043c\u044f","Getting Sick at the Wrong Time")
B.byd=new A.e(u.DA,"You get sick right on the eve of a long-awaited event.")
B.bPR=new A.e("\u0422\u0435\u043b\u043e \u043f\u0440\u043e\u0441\u0438\u0442 \u043e\u0442\u0434\u044b\u0445\u0430. \u042f {\u0442\u0430\u043a\u043e\u0439|\u0442\u0430\u043a\u0430\u044f}, {\u043a\u0430\u043a\u043e\u0439|\u043a\u0430\u043a\u0430\u044f} \u0435\u0441\u0442\u044c, \u0438 \u0441\u0435\u0439\u0447\u0430\u0441 \u044f \u0431\u043e\u043b\u0435\u044e.","My body is asking for rest. I am who I am, and right now I am sick.")
B.bxg=new A.e("\u041f\u043e\u0447\u0435\u043c\u0443 \u044d\u0442\u043e \u0441\u043b\u0443\u0447\u0438\u043b\u043e\u0441\u044c \u0438\u043c\u0435\u043d\u043d\u043e \u0441\u043e \u043c\u043d\u043e\u0439?!","Why did this have to happen to me?!")
B.bIA=new A.e(u.ph,"I'll go anyway\u2014I can't let people down. My needs come later.")
B.bvg=new A.e(u.uT,"I'll tell my loved ones that I'm sad to miss it.")
B.bvn=new A.e("\u0412\u0441\u0435\u0433\u0434\u0430 \u0442\u0430\u043a. \u0412\u043f\u0435\u0440\u0435\u0434\u0438 \u043d\u0438\u0447\u0435\u0433\u043e \u0445\u043e\u0440\u043e\u0448\u0435\u0433\u043e.","Always like this. Nothing good lies ahead.")
B.bK0=new A.e("\u0414\u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u0434\u0440\u0443\u0433\u043e\u043c\u0443","Someone Else Wins")
B.bCR=new A.e(u.ef,"A friend gets exactly what you have been dreaming of: a spot, a prize, or attention.")
B.buh=new A.e(u.M,"It's sad and happy at the same time. That happens\u2014feeling sad is normal.")
B.bNX=new A.e("\u041f\u043e\u0447\u0435\u043c\u0443 \u0435\u043c\u0443, \u0430 \u043d\u0435 \u043c\u043d\u0435? \u041d\u0435\u0441\u043f\u0440\u0430\u0432\u0435\u0434\u043b\u0438\u0432\u043e!","Why them and not me? That's unfair!")
B.bJr=new A.e("\u041d\u0435 {\u0437\u0430\u0441\u043b\u0443\u0436\u0438\u043b|\u0437\u0430\u0441\u043b\u0443\u0436\u0438\u043b\u0430}. \u041d\u0435 \u0431\u0443\u0434\u0443 \u043f\u043e\u0437\u0434\u0440\u0430\u0432\u043b\u044f\u0442\u044c.","They didn't earn it. I won't congratulate them.")
B.bIS=new A.e(u.EB,"I'll congratulate them. Someone else's joy doesn't take away mine.")
B.bww=new A.e("\u041c\u043d\u0435 \u0442\u0430\u043a\u043e\u0433\u043e \u043d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 \u0432\u0438\u0434\u0430\u0442\u044c.","I'll never get something like that.")
B.bFA=new A.e("\u0421\u0432\u043e\u044f \u0447\u0435\u0440\u0442\u0430","A Personal Flaw")
B.bOD=new A.e(u.aF,"You notice a trait in yourself that you haven't liked for a long time.")
B.by1=new A.e("\u042f {\u0442\u0430\u043a\u043e\u0439|\u0442\u0430\u043a\u0430\u044f}, {\u043a\u0430\u043a\u043e\u0439|\u043a\u0430\u043a\u0430\u044f} \u0435\u0441\u0442\u044c, \u2014 \u0438 \u043c\u043e\u0433\u0443 \u043c\u0435\u043d\u044f\u0442\u044c\u0441\u044f \u043f\u043e\u043d\u0435\u043c\u043d\u043e\u0433\u0443.","I am who I am\u2014and I can change little by little.")
B.byC=new A.e("\u0421\u043e \u043c\u043d\u043e\u0439 \u0447\u0442\u043e-\u0442\u043e \u0433\u043b\u0443\u0431\u043e\u043a\u043e \u043d\u0435 \u0442\u0430\u043a.","There is something deeply wrong with me.")
B.btP=new A.e(u.qP,"I'll root it out completely. Either perfect or nothing at all.")
B.bA9=new A.e("\u0418\u0434\u0435\u0430\u043b\u044c\u043d\u044b\u0445 \u043b\u044e\u0434\u0435\u0439 \u043d\u0435 \u0431\u044b\u0432\u0430\u0435\u0442.","Perfect people don't exist.")
B.bLD=new A.e(u.m8,"It's just the circumstances. Everything should have been different.")
B.bsg=new A.e("\u041c\u043e\u043b\u0447\u0430\u043b\u0438\u0432\u0430\u044f \u0437\u0430\u0431\u043e\u0442\u0430","Silent Care")
B.bwO=new A.e(u.Cd,"One of your loved ones silently does something nice for you.")
B.bvR=new A.e(u.q9,"I'll say thank you: I have something to be grateful for.")
B.bOH=new A.e("\u0422\u0430\u043a \u0438 \u0434\u043e\u043b\u0436\u043d\u043e \u0431\u044b\u0442\u044c. \u041c\u043d\u0435 \u0432\u0441\u0435 \u0434\u043e\u043b\u0436\u043d\u044b.","That's exactly how it should be. Everyone owes me.")
B.bvj=new A.e(u.Bw,"Something is fishy here. Everyone wants something from me.")
B.bEf=new A.e("\u041d\u0435\u043b\u043e\u0432\u043a\u043e. \u042f \u044d\u0442\u043e\u0433\u043e \u043d\u0435 {\u0437\u0430\u0441\u043b\u0443\u0436\u0438\u043b|\u0437\u0430\u0441\u043b\u0443\u0436\u0438\u043b\u0430}.","It feels awkward. I haven't earned this.")
B.bSc=new A.e("\u041f\u0440\u0438\u043c\u0443 \u0438 \u0442\u043e\u0436\u0435 \u0447\u0435\u043c-\u043d\u0438\u0431\u0443\u0434\u044c \u043f\u043e\u0440\u0430\u0434\u0443\u044e.","I'll accept it and find a way to make them happy too.")
B.bET=new A.e("\u0420\u0435\u0437\u043a\u0438\u0439 \u043e\u0442\u0432\u0435\u0442","A Sharp Reply")
B.bFz=new A.e(u.Q,"A close person answers you sharply for no apparent reason.")
B.byX=new A.e("\u041d\u0430\u0432\u0435\u0440\u043d\u043e\u0435, \u0443 {\u043d\u0435\u0433\u043e|\u043d\u0435\u0451} \u0442\u0440\u0443\u0434\u043d\u044b\u0439 \u0434\u0435\u043d\u044c. \u0423 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0441\u0432\u043e\u044f \u043f\u0440\u0438\u0447\u0438\u043d\u0430.","They are probably having a hard day. Everyone has their own reason.")
B.bRE=new A.e("\u041e\u0442\u0432\u0435\u0447\u0443 \u0442\u0430\u043a \u0436\u0435. \u0420\u0430\u0441\u0441\u043b\u0430\u0431\u043b\u044e\u0441\u044c \u2014 \u0443\u043d\u0438\u0447\u0442\u043e\u0436\u0430\u0442.","I'll answer the same way. If I let my guard down, they'll destroy me.")
B.bE5=new A.e("\u041e\u043f\u044f\u0442\u044c \u044f \u043c\u0435\u0448\u0430\u044e. \u042f \u043e\u0431\u0443\u0437\u0430.","I'm in the way again. I'm just a burden.")
B.bG5=new A.e(u.cc,"I'll calmly mention that I don't appreciate that tone.")
B.bI0=new A.e("\u041e\u0442\u0433\u043e\u0440\u043e\u0436\u0443\u0441\u044c. \u041c\u043d\u0435 \u043d\u0438\u043a\u0442\u043e \u043d\u0435 \u043d\u0443\u0436\u0435\u043d.","I'll shut myself off. I don't need anyone.")
B.bvK=new A.e("\u041e\u0434\u0438\u043d\u043e\u043a\u0438\u0439 \u0432\u0435\u0447\u0435\u0440","A Lonely Evening")
B.bNM=new A.e("\u0412\u0435\u0447\u0435\u0440, \u0432\u0441\u0435 \u0437\u0430\u043d\u044f\u0442\u044b, \u0438 \u0442\u0435\u0431\u0435 \u043e\u0434\u0438\u043d\u043e\u043a\u043e.","It is evening, everyone is busy, and you feel lonely.")
B.bLk=new A.e(u.dP,"I'll write to someone first. We are all connected.")
B.bri=new A.e("\u041d\u0438\u043a\u043e\u043c\u0443 \u044f \u043f\u043e-\u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0435\u043c\u0443 \u043d\u0435 {\u043d\u0443\u0436\u0435\u043d|\u043d\u0443\u0436\u043d\u0430}.","No one truly needs me.")
B.bRT=new A.e("\u0412\u0441\u0435 \u0440\u0430\u043d\u043e \u0438\u043b\u0438 \u043f\u043e\u0437\u0434\u043d\u043e \u0443\u0445\u043e\u0434\u044f\u0442.","Everyone leaves sooner or later.")
B.brP=new A.e(u.oe,"I'll take care of myself: tea, a blanket, and my favorite music.")
B.bM9=new A.e(u.i,"I'll stare at the screen until late at night just to avoid feeling anything.")
B.bxL=new A.e("\u0422\u044f\u0436\u0451\u043b\u044b\u0435 \u0441\u0443\u043c\u043a\u0438","Heavy Bags")
B.bML=new A.e(u.ir,"An elderly neighbor asks you to help carry their bags, but you are in a big hurry.")
B.buo=new A.e("\u041f\u043e\u043c\u043e\u0433\u0443: \u0434\u0432\u0435 \u043c\u0438\u043d\u0443\u0442\u044b \u2014 \u0438 \u043a\u043e\u043c\u0443-\u0442\u043e \u043b\u0435\u0433\u0447\u0435.","I'll help: two minutes, and someone's life is a bit easier.")
B.bOc=new A.e("\u041d\u0435 \u043c\u043e\u044f \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u0430.","Not my problem.")
B.bIX=new A.e(u.ko,"I'll help, be late, and scold myself later: I just don't know how to say no.")
B.bxb=new A.e(u.nb,"I'll be honest and say I'm in a hurry, and suggest who else they could ask.")
B.bGQ=new A.e("\u0412\u0434\u0440\u0443\u0433 \u044d\u0442\u043e \u0443\u043b\u043e\u0432\u043a\u0430?","What if it's a trick?")
B.bCE=new A.e("\u0427\u0443\u0436\u043e\u0439 \u0443\u0441\u043f\u0435\u0445 \u0432 \u043b\u0435\u043d\u0442\u0435","Someone Else's Success in Your Feed")
B.bAE=new A.e(u.EE,"In your feed, you see an acquaintance showing off a big achievement.")
B.bJl=new A.e("\u041f\u043e\u0440\u0430\u0434\u0443\u044e\u0441\u044c \u0437\u0430 {\u043d\u0435\u0433\u043e|\u043d\u0435\u0451}: \u0447\u0443\u0436\u0430\u044f \u0440\u0430\u0434\u043e\u0441\u0442\u044c \u043d\u0435 \u043e\u0442\u043d\u0438\u043c\u0430\u0435\u0442 \u043c\u043e\u0435\u0439.","I'll be happy for them: someone else's joy doesn't take away mine.")
B.bJf=new A.e(u.ta,"Everyone has a life, but nothing good lies ahead for me.")
B.bse=new A.e("\u041d\u0430\u0432\u0435\u0440\u043d\u044f\u043a\u0430 \u0432\u0440\u0451\u0442. \u0412\u0435\u0440\u0438\u0442\u044c \u043d\u0435\u043b\u044c\u0437\u044f \u043d\u0438\u043a\u043e\u043c\u0443.","They must be lying. You can't trust anyone.")
B.bSs=new A.e(u.oT,"Envy points to what I want. I wonder what that is?")
B.bGh=new A.e("\u042f \u0445\u0443\u0436\u0435 \u0432\u0441\u0435\u0445.","I am worse than everyone else.")
B.bBV=new A.e("\u041f\u043e\u043a\u0430\u0437\u0430\u0442\u044c \u0441\u0432\u043e\u0451","Showing Your Work")
B.bJS=new A.e(u.z8,"You create something of your own (a drawing, a song, a text, a craft), and someone suggests showing it to others.")
B.bJa=new A.e("\u041f\u043e\u043a\u0430\u0436\u0443: \u043c\u043e\u0451 \u0442\u0432\u043e\u0440\u0447\u0435\u0441\u0442\u0432\u043e \u0443\u043d\u0438\u043a\u0430\u043b\u044c\u043d\u043e.","I'll show it: my creativity is unique.")
B.bEQ=new A.e("\u042d\u0442\u043e \u0441\u043b\u0438\u0448\u043a\u043e\u043c \u0433\u043b\u0443\u043f\u043e, \u0447\u0442\u043e\u0431\u044b \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0442\u044c.","It's too silly to show.")
B.bJP=new A.e("\u0417\u0430\u0441\u043c\u0435\u044e\u0442. \u0421\u043f\u0440\u044f\u0447\u0443.","They'll laugh at me. I'll hide it.")
B.bG6=new A.e(u.lN,"I'll show it to at least one person. It's okay to be seen.")
B.bsM=new A.e("\u0414\u0430 \u043a\u043e\u043c\u0443 \u044d\u0442\u043e \u043d\u0430\u0434\u043e. \u0412\u0441\u0451 \u0431\u0435\u0441\u0441\u043c\u044b\u0441\u043b\u0435\u043d\u043d\u043e.","Who cares anyway. It's all pointless.")
B.bIQ=new A.e("\u0414\u0440\u0443\u0437\u044c\u044f \u0432\u044b\u0431\u0438\u0440\u0430\u044e\u0442","Friends are Choosing")
B.bO3=new A.e(u._,"Your friends are picking a place to go, and they choose something you don't like at all.")
B.bRo=new A.e(u.eG,"I'll say what I want\u2014maybe we can find a compromise.")
B.bzf=new A.e("\u041f\u0440\u043e\u0449\u0435 \u0441\u043e\u0433\u043b\u0430\u0441\u0438\u0442\u044c\u0441\u044f.","It's just easier to go along with it.")
B.byR=new A.e("\u041d\u0443 \u0438 \u0438\u0434\u0438\u0442\u0435 \u0431\u0435\u0437 \u043c\u0435\u043d\u044f. \u041c\u043d\u0435 \u043d\u0438\u043a\u0442\u043e \u043d\u0435 \u043d\u0443\u0436\u0435\u043d.","Go without me then. I don't need anyone.")
B.bDM=new A.e(u.df,"I'll go since it's important to them, and next time I'll choose.")
B.bOn=new A.e("\u0412\u0441\u0451 \u0440\u0430\u0432\u043d\u043e \u043c\u0435\u043d\u044f \u043d\u0435 \u043f\u043e\u0441\u043b\u0443\u0448\u0430\u044e\u0442.","They won't listen to me anyway.")
B.bDR=new A.e("\xab\u0427\u0442\u043e \u0441 \u0442\u043e\u0431\u043e\u0439?\xbb","'What's Wrong?'")
B.bOI=new A.e(u.xN,"You are feeling sad, and someone close asks you: 'What's wrong?'")
B.bJT=new A.e("\u0421\u043a\u0430\u0436\u0443 \u0447\u0435\u0441\u0442\u043d\u043e, \u0447\u0442\u043e \u043c\u043d\u0435 \u0433\u0440\u0443\u0441\u0442\u043d\u043e.","I'll be honest and say that I feel sad.")
B.bAw=new A.e(u.a9,"'Everything is fine,' and I'll smile. My feelings will just tire everyone out.")
B.bMd=new A.e("\u041d\u0435 \u0445\u043e\u0447\u0443 \u0433\u0440\u0443\u0437\u0438\u0442\u044c. \u042f \u0438 \u0442\u0430\u043a \u043e\u0431\u0443\u0437\u0430.","I don't want to weigh them down. I'm a burden anyway.")
B.bG2=new A.e(u.gS,"They won't understand anyway. Don't show what matters to you.")
B.bLt=new A.e("\u041f\u043e\u0434\u0435\u043b\u044e\u0441\u044c: \u0431\u043b\u0438\u0437\u043a\u0438\u0435 \u043c\u043e\u0433\u0443\u0442 \u043f\u043e\u043c\u043e\u0447\u044c.","I'll share: loved ones can be helpful.")
B.btF=new A.e("\u0412\u043b\u0435\u0437\u043b\u0438 \u0431\u0435\u0437 \u043e\u0447\u0435\u0440\u0435\u0434\u0438","Line Cutters")
B.bvs=new A.e(u.B0,"Someone roughly pushes past you and cuts in line.")
B.bOo=new A.e(u.iq,"I'll calmly and firmly state that it's my turn.")
B.bBS=new A.e("\u041f\u0440\u043e\u043c\u043e\u043b\u0447\u0443. \u041d\u0435 \u0432\u044b\u0441\u043e\u0432\u044b\u0432\u0430\u0439\u0441\u044f.","I'll stay silent. Keep a low profile.")
B.bx8=new A.e(u.lW,"I'll stay silent, and then spend the whole day replaying what I should have said.")
B.btI=new A.e(u.A2,"I'll answer just as roughly: if you let your guard down, they'll trample you.")
B.bAi=new A.e(u.pX,"It's unpleasant, but I won't let it ruin my day.")
B.bOJ=new A.e("\u0417\u043e\u0432\u0443\u0442 \u0442\u0430\u043d\u0446\u0435\u0432\u0430\u0442\u044c","Invited to Dance")
B.bLA=new A.e(u.hj,"Everyone is dancing (singing, playing) at the party and they invite you to join.")
B.bFt=new A.e("\u041f\u043e\u0439\u0434\u0443: \u043c\u043d\u0435 \u043c\u043e\u0436\u043d\u043e \u0438\u0433\u0440\u0430\u0442\u044c \u043f\u0440\u043e\u0441\u0442\u043e \u0442\u0430\u043a.","I'll join: I am allowed to play just for fun.")
B.bzn=new A.e("\u0411\u0443\u0434\u0443 \u0432\u044b\u0433\u043b\u044f\u0434\u0435\u0442\u044c \u0433\u043b\u0443\u043f\u043e. \u041f\u043e\u0441\u0438\u0436\u0443.","I'll look silly. I'll just sit out.")
B.bQb=new A.e("\u0413\u043b\u0443\u043f\u043e\u0435 \u0432\u0435\u0441\u0435\u043b\u044c\u0435. \u0412\u0441\u0451 \u044d\u0442\u043e \u0431\u0435\u0441\u0441\u043c\u044b\u0441\u043b\u0435\u043d\u043d\u043e.","Silly fun. It's all pointless.")
B.bOM=new A.e("\u041f\u043e\u0441\u0438\u0436\u0443, \u043f\u043e\u0441\u043c\u043e\u0442\u0440\u044e \u0438 \u043f\u043e\u0434\u043a\u043b\u044e\u0447\u0443\u0441\u044c, \u043a\u043e\u0433\u0434\u0430 \u0437\u0430\u0445\u043e\u0447\u0443. \u042f {\u0442\u0430\u043a\u043e\u0439|\u0442\u0430\u043a\u0430\u044f}, {\u043a\u0430\u043a\u043e\u0439|\u043a\u0430\u043a\u0430\u044f} \u0435\u0441\u0442\u044c.","I'll sit, watch, and join in whenever I want. I am who I am.")
B.bMN=new A.e("\u0418\u0434\u0443! \u0421\u043c\u043e\u0442\u0440\u0435\u0442\u044c \u043d\u0430 \u043c\u0435\u043d\u044f \u2014 \u043d\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u043e.","I'm in! It's okay to be seen.")
B.bFP=new A.e("\u0412\u0435\u0447\u0435\u0440 \u0442\u044f\u0436\u0451\u043b\u043e\u0433\u043e \u0434\u043d\u044f","Evening of a Hard Day")
B.bEo=new A.e("\u041d\u0430\u0441\u0442\u0443\u043f\u0430\u0435\u0442 \u0432\u0435\u0447\u0435\u0440 \u043e\u0447\u0435\u043d\u044c \u0442\u044f\u0436\u0451\u043b\u043e\u0433\u043e \u0434\u043d\u044f.","The evening of a very difficult day arrives.")
B.bQ4=new A.e("\u0427\u0435\u043c\u0443 \u043c\u0435\u043d\u044f \u043d\u0430\u0443\u0447\u0438\u043b \u044d\u0442\u043e\u0442 \u0434\u0435\u043d\u044c?","What did this day teach me?")
B.bK8=new A.e("\u0417\u0430\u0447\u0435\u043c \u0432\u043e\u043e\u0431\u0449\u0435 \u0432\u0441\u0451 \u044d\u0442\u043e?","What is it all for anyway?")
B.byK=new A.e("\u0417\u0430\u0432\u0442\u0440\u0430 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u0441\u0432\u0435\u0442\u043b\u0435\u0435.","Tomorrow might be brighter.")
B.bKU=new A.e("\u042d\u0442\u043e \u0432\u0441\u0451 \u0438\u0437-\u0437\u0430 \u0434\u0440\u0443\u0433\u0438\u0445. \u041d\u0435\u0441\u043f\u0440\u0430\u0432\u0435\u0434\u043b\u0438\u0432\u043e!","This is all because of others. It's unfair!")
B.bKo=new A.e(u.zk,"I'll note one thing that actually went well.")
B.bRe=new A.e("\u0427\u0435\u0440\u0435\u0437 \u043f\u044f\u0442\u044c \u043b\u0435\u0442","In Five Years")
B.bNs=new A.e(u.tV,"Someone asks you: 'Where do you see yourself in five years?'")
B.bLr=new A.e("\u042f \u0441\u043e\u0437\u0434\u0430\u044e \u0441\u0432\u043e\u044e \u0438\u0441\u0442\u043e\u0440\u0438\u044e \u2014 \u0435\u0441\u0442\u044c \u043f\u0430\u0440\u0430 \u0438\u0434\u0435\u0439.","I am creating my own story\u2014I have a couple of ideas.")
B.bIG=new A.e("\u0412\u043f\u0435\u0440\u0435\u0434\u0438 \u043d\u0438\u0447\u0435\u0433\u043e \u0445\u043e\u0440\u043e\u0448\u0435\u0433\u043e.","Nothing good lies ahead.")
B.bSy=new A.e(u.CE,"I don't know\u2014and that's okay. The future can be kind.")
B.bxh=new A.e(u.ai,"Whatever others decide\u2014very little depends on me.")
B.buw=new A.e(u.l0,"I want to be part of something bigger than myself.")
B.bNZ=new A.e("\u0417\u043d\u0430\u043a\u043e\u043c\u0430\u044f \u0442\u0440\u0443\u0434\u043d\u043e\u0441\u0442\u044c","A Familiar Struggle")
B.bJq=new A.e(u.sh,"A younger friend or a newcomer goes through a difficulty that is very familiar to you.")
B.bPT=new A.e(u.jO,"I'll tell them what helped me: my experience might help someone.")
B.bBR=new A.e("\u041f\u0443\u0441\u0442\u044c {\u0441\u0430\u043c|\u0441\u0430\u043c\u0430} \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044f. \u041c\u043e\u044f \u0431\u043e\u043b\u044c \u0431\u044b\u043b\u0430 \u0431\u043e\u043b\u044c\u043d\u0435\u0435.","Let them figure it out themselves. My pain was more painful.")
B.bCW=new A.e("\u041c\u043e\u0439 \u043e\u043f\u044b\u0442 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0441\u0442\u043e\u0438\u0442.","My experience is worth nothing.")
B.bG9=new A.e(u.fF,"I'll just stay by their side: small actions matter too.")
B.bzp=new A.e("\u041d\u0435 \u043f\u043e\u043b\u0435\u0437\u0443 \u2014 \u0432\u0434\u0440\u0443\u0433 \u0441\u043a\u0430\u0436\u0443 \u0433\u043b\u0443\u043f\u043e\u0441\u0442\u044c.","I won't interfere\u2014what if I say something silly.")
B.bxi=new A.e("\u0417\u0430\u043a\u0430\u0442","Sunset")
B.bPL=new A.e(u.o4,"On your way, you happen to see a very beautiful sunset.")
B.bFj=new A.e(u.eT,"I'll stop for a minute: there is beauty all around.")
B.bzd=new A.e("\u041a\u0440\u0430\u0441\u0438\u0432\u043e, \u043d\u043e \u043a\u0430\u043a\u043e\u0439 \u0432 \u044d\u0442\u043e\u043c \u0441\u043c\u044b\u0441\u043b.","It's pretty, but what's the point of it.")
B.bPB=new A.e(u.vR,"I'll take a picture and send it to someone close. We are all connected.")
B.bJG=new A.e("\u0412 \u043a\u0430\u0436\u0434\u043e\u043c \u0434\u043d\u0435 \u0435\u0441\u0442\u044c \u0438\u0441\u043a\u0440\u0430.","There is a spark in every single day.")
B.bDh=new A.e(u.iL,"No time. Until I finish everything, I am not allowed to rest.")
B.bDo=new A.e("\u041f\u0440\u043e\u0442\u0438\u0432 \u0441\u0432\u043e\u0438\u0445 \u0446\u0435\u043d\u043d\u043e\u0441\u0442\u0435\u0439","Against Your Values")
B.bNm=new A.e(u.s,"Friends suggest doing something that goes against your values: cheating, mocking someone, or breaking a promise.")
B.bQg=new A.e("\u041e\u0442\u043a\u0430\u0436\u0443\u0441\u044c: \u044f \u0437\u043d\u0430\u044e, \u0447\u0442\u043e \u0434\u043b\u044f \u043c\u0435\u043d\u044f \u0432\u0430\u0436\u043d\u043e.","I'll refuse: I know what matters to me.")
B.bvP=new A.e("\u0421\u043e\u0433\u043b\u0430\u0448\u0443\u0441\u044c, \u043b\u0438\u0448\u044c \u0431\u044b \u043d\u0435 \u0432\u044b\u0434\u0435\u043b\u044f\u0442\u044c\u0441\u044f.","I'll agree, just to fit in.")
B.bMS=new A.e(u.j2,"I'll refuse gently: I am allowed to say 'no'.")
B.bG0=new A.e(u.AM,"What difference does it make, everything is meaningless anyway.")
B.bF4=new A.e(u.xa,"If I refuse, they'll leave. Everyone leaves sooner or later.")
B.bMT=new A.e("\u041d\u0435 \u0443\u0441\u043d\u0443\u0442\u044c","Can't Sleep")
B.bJb=new A.e(u.zW,"It's night, time for bed, but your thoughts won't let you fall asleep.")
B.bIu=new A.e(u.uu,"I'll place my thoughts on leaves and let them go until morning. This will pass.")
B.bQm=new A.e(u.Dc,"Tomorrow everything will go wrong. I won't handle it.")
B.bzq=new A.e("\u0412\u0434\u0440\u0443\u0433 \u0441\u043b\u0443\u0447\u0438\u0442\u0441\u044f \u0447\u0442\u043e-\u0442\u043e \u0441\u0442\u0440\u0430\u0448\u043d\u043e\u0435?","What if something terrible happens?")
B.bwx=new A.e(u.dm,"I'll take care of myself: a warm drink, slow breathing.")
B.bQT=new A.e("\u0420\u0430\u0437 \u043d\u0435 \u0441\u043f\u043b\u044e \u2014 \u0431\u0443\u0434\u0443 \u043b\u0438\u0441\u0442\u0430\u0442\u044c \u0434\u043e \u0443\u0442\u0440\u0430.","Since I'm not sleeping\u2014I'll just scroll until morning.")
